-- SELECT only. Run after apply. 예/아니오 항목은 모두 예, 그 밖의 값은 precheck의 같은 이름 항목과 같은 값이어야 한다.
select 'history row present' as item,case when (select count(*) from supabase_migrations.schema_migrations where version='20261029233000' and name='tg_sender_set_self')=1 then '예' else '아니오' end as value
union all select 'set_self function: definer, empty search_path, no anon or PUBLIC execute',case when exists(select 1 from pg_proc p where p.oid=to_regprocedure('public.app_tg_sender_set_self(uuid,boolean)') and p.prosecdef and p.proconfig=array['search_path=""'] and not has_function_privilege('anon',p.oid,'execute') and coalesce(p.proacl::text,'')!~'(^|[{,])=') then '예' else '아니오' end
union all select 'set_self function: authenticated only',case when has_function_privilege('authenticated','public.app_tg_sender_set_self(uuid,boolean)','execute') and not has_function_privilege('service_role','public.app_tg_sender_set_self(uuid,boolean)','execute') and not has_function_privilege('anon','public.app_tg_sender_set_self(uuid,boolean)','execute') then '예' else '아니오' end
union all select 'sender tables: authenticated still read only, service_role and anon no privilege',case when not has_table_privilege('authenticated','public.app_tg_senders','insert,update,delete') and not has_any_column_privilege('service_role','public.app_tg_senders','select,insert,update') and not has_any_column_privilege('anon','public.app_tg_senders','select,insert,update') then '예' else '아니오' end
union all select 'sender tables rows',(select count(*)::text from public.app_tg_senders)||'/'||(select count(*)::text from public.app_tg_day_senders)
union all select 'sender tables grants policies hash',md5(coalesce((select string_agg(c.relname||':'||c.relrowsecurity::text||':'||coalesce(c.relacl::text,''),',' order by c.relname) from pg_class c where c.oid in(to_regclass('public.app_tg_senders'),to_regclass('public.app_tg_day_senders'))),'')
  ||coalesce((select string_agg(p.polname::text||p.polcmd::text||p.polroles::text||coalesce(pg_get_expr(p.polqual,p.polrelid),''),',' order by p.polname) from pg_policy p where p.polrelid in(to_regclass('public.app_tg_senders'),to_regclass('public.app_tg_day_senders'))),''));
